  "loc.st.why":     { fr: "La base contient des lignes créées avant l'existence des établissements. Sans établissement, elles n'apparaîtraient plus dans aucun point de vente.", en: "The database holds rows created before the locations existed. With no location they would no longer appear in any point of sale.", it: "Nel database ci sono righe create prima che le sedi esistessero. Senza una sede non comparirebbero più in nessun punto vendita.", nl: "De database bevat rijen van vóór het bestaan van de vestigingen. Zonder vestiging zouden ze in geen enkel verkooppunt meer verschijnen.", es: "La base contiene filas creadas antes de que existieran los establecimientos. Sin establecimiento ya no aparecerían en ningún punto de venta." },
  "loc.st.which":   { fr: "À quel établissement appartiennent-elles ?", en: "Which location do they belong to?", it: "A quale sede appartengono?", nl: "Bij welke vestiging horen ze?", es: "¿A qué establecimiento pertenecen?" },
  "loc.st.count":   { fr: "Seront attribuées :", en: "Will be assigned:", it: "Verranno assegnate:", nl: "Worden toegewezen:", es: "Se asignarán:" },
  "loc.st.warn":    { fr: "Une seule fois, sans retour en arrière. Ce sont des sociétés distinctes : ces recettes resteront attribuées à l'établissement choisi.", en: "Once only, with no undo. These are separate companies: this revenue will stay attributed to the chosen location.", it: "Si fa una volta sola e non si annulla. Sono società diverse: questi incassi resteranno attribuiti alla sede scelta.", nl: "Eenmalig en niet ongedaan te maken. Dit zijn aparte vennootschappen: deze omzet blijft toegewezen aan de gekozen vestiging.", es: "Se hace una sola vez y no se deshace. Son sociedades distintas: estos ingresos quedarán atribuidos al establecimiento elegido." },
  "loc.st.go":      { fr: "Activer", en: "Enable", it: "Attiva", nl: "Inschakelen", es: "Activar" },
  "loc.st.done":    { fr: "Multi-établissement activé · {n} lignes attribuées", en: "Multi-location enabled · {n} rows assigned", it: "Multi-sede attivato · {n} righe assegnate", nl: "Multi-vestiging ingeschakeld · {n} rijen toegewezen", es: "Multiestablecimiento activado · {n} filas asignadas" },
  "loc.err.storicoSede": { fr: "Choisis l'établissement auquel appartient l'historique", en: "Choose the location the history belongs to", it: "Scegli la sede a cui appartiene lo storico", nl: "Kies de vestiging waartoe de historiek behoort", es: "Elige el establecimiento al que pertenece el historial" },
  "loc.err.storicoKo":   { fr: "Attribution de l'historique impossible : rien n'a été activé", en: "Could not assign the history: nothing was enabled", it: "Attribuzione dello storico impossibile: non è stato attivato niente", nl: "Toewijzen van de historiek mislukt: er is niets ingeschakeld", es: "No se pudo atribuir el historial: no se ha activado nada" },
