  "loc.googleHint": { fr: "L'élément se choisit dans la liste des fiches du compte Google connecté : rien à copier à la main.", en: "Pick it from the listings of the connected Google account: nothing to copy by hand.", it: "Si sceglie dall'elenco delle schede dell'account Google collegato: niente da copiare a mano.", nl: "Kies ze uit de vermeldingen van het gekoppelde Google-account: niets om met de hand te kopiëren.", es: "Se elige de la lista de fichas de la cuenta de Google conectada: nada que copiar a mano." },
