  "loc.sezStampa":    { fr: "Impression des tickets", en: "Ticket printing", it: "Stampa dei ticket", nl: "Tickets afdrukken", es: "Impresi\u00f3n de tickets" },
  "loc.printer":      { fr: "Imprimante", en: "Printer", it: "Stampante", nl: "Printer", es: "Impresora" },
  "loc.printerHint":  { fr: "L\u2019imprimante reli\u00e9e \u00e0 ce point de vente. La liste vient du service d\u2019impression\u00a0: choisissez-la, ne tapez pas de num\u00e9ro.", en: "The printer connected to this location. The list comes from the print service: pick it, don\u2019t type a number.", it: "La stampante collegata a questo punto. L\u2019elenco arriva dal servizio di stampa: scegliela, non scrivere un numero.", nl: "De printer van deze vestiging. De lijst komt van de printdienst: kies hem, typ geen nummer.", es: "La impresora de este punto de venta. La lista viene del servicio de impresi\u00f3n: elija, no escriba un n\u00famero." },
  "loc.printNone":    { fr: "Aucune imprimante\u00a0: branchez-la et rechargez.", en: "No printer: connect it and reload.", it: "Nessuna stampante: collegala e ricarica.", nl: "Geen printer: sluit hem aan en herlaad.", es: "Ninguna impresora: con\u00e9ctela y recargue." },
