  "loc.printShort":   { fr: "Imprimante", en: "Printer", it: "Stampante", nl: "Printer", es: "Impresora" },
  "loc.printPaused":  { fr: "automatique d\u00e9sactiv\u00e9e", en: "automatic off", it: "automatica spenta", nl: "automatisch uit", es: "autom\u00e1tica apagada" },
  "itg.print.who":    { fr: "Vaut pour toute l\u2019installation. Avec plusieurs points de vente, chaque fiche peut avoir la sienne et remplace celle-ci.", en: "Applies to the whole installation. With several locations, each one can have its own and overrides this.", it: "Vale per tutta l\u2019installazione. Con piu' punti vendita, ogni scheda puo' avere la sua e sostituisce questa.", nl: "Geldt voor de hele installatie. Met meerdere vestigingen kan elke vestiging een eigen printer hebben die deze vervangt.", es: "Vale para toda la instalaci\u00f3n. Con varios puntos de venta, cada ficha puede tener la suya y sustituye a esta." },
  "loc.sezDest":      { fr: "Plusieurs imprimantes", en: "Several printers", it: "Piu' stampanti", nl: "Meerdere printers", es: "Varias impresoras" },
  "loc.destAdd":      { fr: "Ajouter une destination", en: "Add a destination", it: "Aggiungi una destinazione", nl: "Bestemming toevoegen", es: "A\u00f1adir un destino" },
  "loc.destNome":     { fr: "Nom court", en: "Short name", it: "Nome corto", nl: "Korte naam", es: "Nombre corto" },
  "loc.destCat":      { fr: "Cat\u00e9gories", en: "Categories", it: "Categorie", nl: "Categorie\u00ebn", es: "Categor\u00edas" },
  "loc.destHint":     { fr: "Chaque ligne envoie ses cat\u00e9gories \u00e0 son imprimante. Tout le reste part sur l\u2019imprimante principale ci-dessus\u00a0: rien ne se perd. Le nom appara\u00eet sur le ticket (\u00ab\u00a01/3 \u2014 aussi\u00a0: 2x Bar\u00a0\u00bb), gardez-le court.", en: "Each line sends its categories to its printer. Everything else goes to the main printer above, so nothing is lost. The name appears on the ticket (\u201c1/3 \u2014 also: 2x Bar\u201d), keep it short.", it: "Ogni riga manda le sue categorie alla sua stampante. Tutto il resto esce dalla principale qui sopra: niente si perde. Il nome compare sul ticket (\u00ab1/3 \u2014 anche: 2x Bar\u00bb), tienilo corto.", nl: "Elke regel stuurt zijn categorie\u00ebn naar zijn printer. De rest gaat naar de hoofdprinter hierboven, er gaat niets verloren. De naam staat op het ticket (\u201c1/3 \u2014 ook: 2x Bar\u201d), houd hem kort.", es: "Cada l\u00ednea env\u00eda sus categor\u00edas a su impresora. Todo lo dem\u00e1s sale por la principal de arriba: no se pierde nada. El nombre aparece en el ticket (\u00ab1/3 \u2014 tambi\u00e9n: 2x Bar\u00bb), que sea corto." },
  "loc.err.destDoppia": { fr: "Une cat\u00e9gorie ne peut aller que sur une imprimante\u00a0:", en: "A category can only go to one printer:", it: "Una categoria puo' andare su una stampante sola:", nl: "Een categorie kan maar naar \u00e9\u00e9n printer:", es: "Una categor\u00eda solo puede ir a una impresora:" },
  "loc.printAuto":    { fr: "Imprimer les commandes automatiquement", en: "Print orders automatically", it: "Stampa gli ordini automaticamente", nl: "Bestellingen automatisch afdrukken", es: "Imprimir los pedidos autom\u00e1ticamente" },
  "loc.printTest":    { fr: "Test d\u2019impression", en: "Test print", it: "Stampa di prova", nl: "Testafdruk", es: "Impresi\u00f3n de prueba" },
  // ⚠️ «Envoy\u00e9», pas «imprim\u00e9»: le travail passe par le cloud, la tablette
