  "loc.printKo":      { fr: "Le service d\u2019impression a refus\u00e9\u00a0:", en: "The print service refused:", it: "Il servizio di stampa ha rifiutato:", nl: "De printdienst weigerde:", es: "El servicio de impresi\u00f3n lo rechaz\u00f3:" },
  "loc.err.printer":  { fr: "Num\u00e9ro d\u2019imprimante invalide.", en: "Invalid printer number.", it: "Numero di stampante non valido.", nl: "Ongeldig printernummer.", es: "N\u00famero de impresora no v\u00e1lido." },
  "loc.reviewUrl": { fr: "Lien « Laisser un avis »", en: "\u00ab Leave a review \u00bb link", it: "Link « Lascia una recensione »", nl: "Link \u00ab Laat een review achter \u00bb", es: "Enlace « Deja una reseña »" },
  "loc.reviewShort": { fr: "Lien avis", en: "Review link", it: "Link recensioni", nl: "Reviewlink", es: "Enlace reseñas" },
  "loc.reviewUrlHint": { fr: "Le lien de la fiche Google de CE point : il part dans l'e-mail qui demande un avis. Trois fiches, trois liens.", en: "This location's Google listing link: it goes out in the review request email. Three listings, three links.", it: "Il link della scheda Google di QUESTO punto: parte nell'email che chiede la recensione. Tre schede, tre link.", nl: "De Google-link van DIT punt: hij gaat mee in de e-mail die om een review vraagt. Drie vermeldingen, drie links.", es: "El enlace de la ficha de Google de ESTE punto: se envía en el email que pide la reseña. Tres fichas, tres enlaces." },
  "loc.err.linked":   { fr: "Cet établissement a des données liées : désactive-le au lieu de le supprimer", en: "This location has linked data: deactivate it instead of deleting it", it: "Questa sede ha dati collegati: disattivala invece di eliminarla", nl: "Deze vestiging heeft gekoppelde gegevens: schakel ze uit in plaats van ze te verwijderen", es: "Este establecimiento tiene datos vinculados: desactívalo en lugar de eliminarlo" },
  "print.intro":      { fr: "Catalogue des produits imprimables que le restaurant peut commander à MOODD. Prix par lot, sans TVA, propres à ce client. Active un produit pour qu'il apparaisse dans la page Print du client.", en: "Catalogue of printable products the restaurant can order from MOODD. Prices per batch, VAT excluded, specific to this client. Enable a product so it appears on the client's Print page.", it: "Catalogo dei prodotti stampabili che il ristorante può ordinare a MOODD. Prezzi per lotto, IVA esclusa, specifici per questo cliente. Attiva un prodotto perché appaia nella pagina Print del cliente.", nl: "Catalogus van afdrukbare producten die het restaurant bij MOODD kan bestellen. Prijzen per partij, excl. btw, specifiek voor deze klant. Activeer een product zodat het op de Print-pagina van de klant verschijnt.", es: "Catálogo de productos imprimibles que el restaurante puede pedir a MOODD. Precios por lote, sin IVA, propios de este cliente. Activa un producto para que aparezca en la página Print del cliente." },
