  "print.removeTier": { fr: "Retirer cette quantité", en: "Remove this quantity", it: "Rimuovi questa quantità", nl: "Deze hoeveelheid verwijderen", es: "Eliminar esta cantidad" },
  "print.reset":      { fr: "Réinitialiser aux prix conseillés", en: "Reset to suggested prices", it: "Ripristina i prezzi consigliati", nl: "Terug naar aanbevolen prijzen", es: "Restablecer a los precios sugeridos" },
