  "print.removeProd": { fr: "Retirer ce produit du catalogue (effectif apr\u00e8s Enregistrer)", en: "Remove this product from the catalogue (applied on Save)", it: "Togli questo prodotto dal listino (effettivo dopo Salva)", nl: "Dit product uit de catalogus halen (geldt na Opslaan)", es: "Quitar este producto del cat\u00e1logo (efectivo al Guardar)" },
  "print.missing":    { fr: "Page introuvable dans le site : l'aperçu ne s'affichera pas.", en: "Page not found in the site: the preview won't show.", it: "Pagina non trovata nel sito: l'anteprima non si vedrà.", nl: "Pagina niet gevonden in de site: het voorbeeld wordt niet getoond.", es: "Página no encontrada en el sitio: la vista previa no se mostrará." },
