  "set.hor.impactMsg": { fr: "Le jour sera fermé. Que faire des réservations déjà prises ?", en: "The day will be closed. What to do with the reservations already made?", it: "Il giorno sarà chiuso. Cosa fare con le prenotazioni già effettuate?", nl: "De dag wordt gesloten. Wat doe je met de reeds gemaakte reserveringen?", es: "El día estará cerrado. ¿Qué hacer con las reservas ya realizadas?" },
  "set.hor.impactCancel": { fr: "Annuler et prévenir les clients par email", en: "Cancel and notify customers by email", it: "Annulla e avvisa i clienti via email", nl: "Annuleren en klanten per e-mail verwittigen", es: "Anular y avisar a los clientes por correo" },
  "set.hor.impactKeep": { fr: "Garder les réservations", en: "Keep the reservations", it: "Mantieni le prenotazioni", nl: "Reserveringen behouden", es: "Mantener las reservas" },
  "set.hor.cancelledEmailed": { fr: "réservation(s) annulée(s), clients prévenus par email.", en: "reservation(s) cancelled, customers notified by email.", it: "prenotazione/i annullata/e, clienti avvisati via email.", nl: "reservering(en) geannuleerd, klanten per e-mail verwittigd.", es: "reserva(s) anulada(s), clientes avisados por correo." },
  "set.hor.dayCreatedCancelErr": { fr: "Jour créé, mais annulation des réservations impossible.", en: "Day created, but reservations could not be cancelled.", it: "Giorno creato, ma annullamento delle prenotazioni impossibile.", nl: "Dag aangemaakt, maar reserveringen konden niet worden geannuleerd.", es: "Día creado, pero no se pudieron anular las reservas." },

  // ----- Tab Réservations -----
  "set.res.cornerStyle": { fr: "Style des angles du widget", en: "Widget corner style", it: "Stile degli angoli del widget", nl: "Hoekstijl van de widget", es: "Estilo de las esquinas del widget" },
  "set.res.cornerHint": { fr: "Assorti au design du site : angles droits ou arrondis.", en: "Matched to the site design: square or rounded corners.", it: "In linea con il design del sito: angoli retti o arrotondati.", nl: "Afgestemd op het ontwerp van de site: rechte of afgeronde hoeken.", es: "A juego con el diseño del sitio: esquinas rectas o redondeadas." },
  "set.res.cornerSquare": { fr: "Droits", en: "Square", it: "Retti", nl: "Recht", es: "Rectas" },
  "set.res.cornerRounded": { fr: "Arrondis", en: "Rounded", it: "Arrotondati", nl: "Afgerond", es: "Redondeadas" },
  "set.res.autoAccept": { fr: "Accepter tout de suite", en: "Accept immediately", it: "Accetta subito", nl: "Meteen aanvaarden", es: "Aceptar de inmediato" },
  "set.res.autoAcceptHint": { fr: "ACTIVÉ : les réservations sont confirmées automatiquement s'il y a de la place. DÉSACTIVÉ : le widget envoie une demande (statut « En attente ») et c'est vous qui confirmez — le client reçoit l'email de confirmation à ce moment-là.", en: "ON: reservations are confirmed automatically when there is room. OFF: the widget sends a request (status « Pending ») and you confirm it — the customer receives the confirmation email at that point.", it: "ATTIVO: le prenotazioni vengono confermate automaticamente se c'è posto. DISATTIVO: il widget invia una richiesta (stato « In attesa ») e la confermi tu — il cliente riceve l'email di conferma in quel momento.", nl: "AAN: reserveringen worden automatisch bevestigd als er plaats is. UIT: de widget stuurt een aanvraag (status « In afwachting ») en jij bevestigt — de klant krijgt dan de bevestigingsmail.", es: "ACTIVADO: las reservas se confirman automáticamente si hay sitio. DESACTIVADO: el widget envía una solicitud (estado « En espera ») y tú la confirmas — el cliente recibe el correo de confirmación en ese momento." },
  "set.res.zones": { fr: "Sections & couverts", en: "Sections & covers", it: "Sezioni e coperti", nl: "Secties & couverts", es: "Secciones y cubiertos" },
  "set.res.zonesHint": { fr: "Ex. Intérieur 40, Terrasse 60. Le total est la somme des sections.", en: "E.g. Indoor 40, Terrace 60. The total is the sum of the sections.", it: "Es. Interno 40, Terrazza 60. Il totale è la somma delle sezioni.", nl: "Bijv. Binnen 40, Terras 60. Het totaal is de som van de secties.", es: "Ej. Interior 40, Terraza 60. El total es la suma de las secciones." },
  "set.res.addZone": { fr: "+ Ajouter une section", en: "+ Add a section", it: "+ Aggiungi una sezione", nl: "+ Sectie toevoegen", es: "+ Añadir una sección" },
  "set.res.addZoneFirst": { fr: "Ajoute d'abord une section.", en: "Add a section first.", it: "Aggiungi prima una sezione.", nl: "Voeg eerst een sectie toe.", es: "Añade primero una sección." },
  "set.res.zoneNamePh": { fr: "Ex. Intérieur", en: "E.g. Indoor", it: "Es. Interno", nl: "Bijv. Binnen", es: "Ej. Interior" },
  "set.res.floorPlan": { fr: "Plan de salle", en: "Floor plan", it: "Piantina della sala", nl: "Zaalplan", es: "Plano de sala" },
  "set.res.floorPlanHint": { fr: "Choisis une section pour dessiner ses tables (s'ouvre dans une fenêtre). Interrupteur ACTIVÉ : les places réelles sont celles des tables dessinées — les couverts des sections sont ignorés.", en: "Choose a section to draw its tables (opens in a window). Switch ON: the real seats are those of the drawn tables — the section covers are ignored.", it: "Scegli una sezione per disegnare i suoi tavoli (si apre in una finestra). Interruttore ATTIVO: i posti reali sono quelli dei tavoli disegnati — i coperti delle sezioni sono ignorati.", nl: "Kies een sectie om de tafels ervan te tekenen (opent in een venster). Schakelaar AAN: de echte plaatsen zijn die van de getekende tafels — de couverts van de secties worden genegeerd.", es: "Elige una sección para dibujar sus mesas (se abre en una ventana). Interruptor ACTIVADO: las plazas reales son las de las mesas dibujadas — los cubiertos de las secciones se ignoran." },
  "set.res.autoTables": { fr: "Attribuer les tables automatiquement", en: "Assign tables automatically", it: "Assegna i tavoli automaticamente", nl: "Tafels automatisch toewijzen", es: "Asignar las mesas automáticamente" },
  "set.res.autoTablesHint": { fr: "ACTIVÉ : le moteur choisit les tables (la plus petite combinaison qui suffit, sections prioritaires d'abord). DÉSACTIVÉ : seuls les couverts comptent — vous attribuez les tables à la main dans la fenêtre de réservation.", en: "ON: the engine picks the tables (the smallest combination that fits, priority sections first). OFF: only the covers count — you assign the tables by hand in the reservation window.", it: "ATTIVO: il motore sceglie i tavoli (la combinazione più piccola sufficiente, prima le sezioni prioritarie). DISATTIVO: contano solo i coperti — assegni i tavoli a mano nella finestra di prenotazione.", nl: "AAN: de motor kiest de tafels (de kleinste combinatie die volstaat, prioritaire secties eerst). UIT: alleen de couverts tellen — je wijst de tafels manueel toe in het reserveringsvenster.", es: "ACTIVADO: el motor elige las mesas (la combinación más pequeña que baste, primero las secciones prioritarias). DESACTIVADO: solo cuentan los cubiertos — tú asignas las mesas a mano en la ventana de reserva." },
