  "set.res.zoneChoice": { fr: "Choix de la section par le client", en: "Section choice by the customer", it: "Scelta della sezione da parte del cliente", nl: "Sectiekeuze door de klant", es: "Elección de la sección por el cliente" },
  "set.res.zoneChoiceHint": { fr: "Activé : le client choisit sa section (Intérieur, Terrasse…). Désactivé : il réserve simplement, vous placez.", en: "On: the customer chooses their section (Indoor, Terrace…). Off: they simply book, you seat them.", it: "Attivo: il cliente sceglie la sua sezione (Interno, Terrazza…). Disattivo: prenota e basta, li sistemi tu.", nl: "Aan: de klant kiest zijn sectie (Binnen, Terras…). Uit: hij reserveert gewoon, jij plaatst.", es: "Activado: el cliente elige su sección (Interior, Terraza…). Desactivado: solo reserva, tú lo ubicas." },
  "set.res.services": { fr: "Services de réservation", en: "Reservation services", it: "Servizi di prenotazione", nl: "Reserveringsdiensten", es: "Servicios de reserva" },
  "set.res.servicesHint": { fr: "Jusqu'à 5 plages : nom, horaires, jours d'application, durée d'occupation d'une table (min) et créneau (min). Ex. Midi 12:00–15:00 (Lun–Ven), table 60, créneau 15.", en: "Up to 5 slots: name, times, days of application, table occupancy duration (min) and slot (min). E.g. Midday 12:00–15:00 (Mon–Fri), table 60, slot 15.", it: "Fino a 5 fasce: nome, orari, giorni di applicazione, durata di occupazione di un tavolo (min) e fascia (min). Es. Pranzo 12:00–15:00 (Lun–Ven), tavolo 60, fascia 15.", nl: "Tot 5 tijdvakken: naam, uren, toepassingsdagen, bezettingsduur van een tafel (min) en tijdvak (min). Bijv. Middag 12:00–15:00 (Ma–Vr), tafel 60, tijdvak 15.", es: "Hasta 5 franjas: nombre, horarios, días de aplicación, duración de ocupación de una mesa (min) y franja (min). Ej. Mediodía 12:00–15:00 (Lun–Vie), mesa 60, franja 15." },
  "set.res.addService": { fr: "+ Ajouter un service", en: "+ Add a service", it: "+ Aggiungi un servizio", nl: "+ Dienst toevoegen", es: "+ Añadir un servicio" },
  "set.res.maxPeople": { fr: "Personnes maximum par réservation", en: "Maximum people per reservation", it: "Persone massime per prenotazione", nl: "Maximum personen per reservering", es: "Personas máximas por reserva" },
  "set.res.maxPeopleHint": { fr: "Au-delà de ce nombre, le widget invite à appeler le restaurant.", en: "Above this number, the widget invites the customer to call the restaurant.", it: "Oltre questo numero, il widget invita a chiamare il ristorante.", nl: "Boven dit aantal nodigt de widget uit om het restaurant te bellen.", es: "Por encima de este número, el widget invita a llamar al restaurante." },
  "set.res.minNotice": { fr: "Délai minimum avant réservation (min)", en: "Minimum notice before booking (min)", it: "Preavviso minimo prima della prenotazione (min)", nl: "Minimale voorafgaande tijd voor reserveren (min)", es: "Antelación mínima antes de reservar (min)" },
  "set.res.minNoticeHint": { fr: "Ex. 240 : à 18:00, le premier créneau proposé est 22:00. 0 = réservable jusqu'à la dernière minute.", en: "E.g. 240: at 18:00, the first slot offered is 22:00. 0 = bookable until the last minute.", it: "Es. 240: alle 18:00, la prima fascia proposta è le 22:00. 0 = prenotabile fino all'ultimo minuto.", nl: "Bijv. 240: om 18:00 is het eerste aangeboden tijdvak 22:00. 0 = reserveerbaar tot op de laatste minuut.", es: "Ej. 240: a las 18:00, la primera franja ofrecida es 22:00. 0 = reservable hasta el último minuto." },
  "set.res.widgetLangs": { fr: "Langues du widget", en: "Widget languages", it: "Lingue del widget", nl: "Talen van de widget", es: "Idiomas del widget" },
  "set.res.widgetLangsHint": { fr: "Le français est toujours actif. Le client change de langue via le globe en haut du widget.", en: "French is always on. The customer switches language via the globe at the top of the widget.", it: "Il francese è sempre attivo. Il cliente cambia lingua con il globo in alto nel widget.", nl: "Frans staat altijd aan. De klant wisselt van taal via de wereldbol bovenaan de widget.", es: "El francés siempre está activo. El cliente cambia de idioma con el globo en la parte superior del widget." },
  "set.res.widgetOpts": { fr: "Options du widget", en: "Widget options", it: "Opzioni del widget", nl: "Widget-opties", es: "Opciones del widget" },
  "set.res.widgetOptsHint": { fr: "Activez pour proposer des options au client (chaise bébé, endroit calme…), puis choisissez lesquelles afficher. Désactivé, aucune option n'apparaît.", en: "Turn on to offer options to the customer (high chair, quiet spot…), then pick which ones to show. Off = no options shown.", it: "Attiva per proporre delle opzioni al cliente (seggiolone, posto tranquillo…), poi scegli quali mostrare. Disattivato: nessuna opzione appare.", nl: "Schakel in om opties aan te bieden (kinderstoel, rustige plek…), kies dan welke te tonen. Uit = geen opties.", es: "Actívalo para ofrecer opciones al cliente (trona, sitio tranquilo…), luego elige cuáles mostrar. Desactivado: no aparece ninguna opción." },
  "set.res.fromEmail": { fr: "Email expéditeur (confirmations clients)", en: "Sender email (customer confirmations)", it: "Email mittente (conferme clienti)", nl: "Afzender-e-mail (klantbevestigingen)", es: "Correo remitente (confirmaciones a clientes)" },
